pure int_add(left: Int, right: Int) -> Int { left + right }
pure float_add(left: Float, right: Float) -> Float { left + right }
print ${int_add(7,11)} ${float_add(1.25,2.5)}
print ${int_add(19,23)} ${float_add(0.5,0.75)}

cases.source:
pure name(entry) { entry.name }
let narrow = {name: "narrow"}
let wide_first = {name: "wide-first", tag: 11, active: true}
let wide_last = {active: false, tag: 23, name: "wide-last"}
let number = {tag: "number", name: 17}
let flag = {name: false, tag: "flag"}
print ${name(narrow)} ${name(wide_first)} ${name(wide_last)} ${name(number)} ${name(flag)}

pure name(entry) { entry.name }
pure forwarded(entry) { name(entry) }
print ${forwarded({name: "small"})} ${forwarded({tag: 9, name: "large"})} ${forwarded({name: 31, active: true})}

pure nested_name(entry) { entry.person.name }
let narrow = {person: {name: "nested"}}
let wide_first = {person: {name: "first", age: 7}, tag: "outer-first"}
let wide_last = {tag: "outer-last", person: {age: 11, name: "last"}}
let number = {tag: false, person: {age: 13, name: 41}}
print ${nested_name(narrow)} ${nested_name(wide_first)} ${nested_name(wide_last)} ${nested_name(number)}

pure string_name(entry) {
  let value: Str = entry.name
  value
}
let _ = string_name({name: 17})

pure infinite(entry) -> Int {
  if false { infinite(entry.name) } else { 0 }
}
let _ = infinite({name: 7})

pure add(left, right) { left + right }
let integer: Int = add(7, 11)
let decimal: Float = add(1.25, 2.5)
print ${integer} ${decimal}

pure add(left, right) { left + right }
pure forwarded(left, right) { add(left, right) }
let integer: Int = forwarded(19, 23)
let decimal: Float = forwarded(0.5, 0.75)
print ${integer} ${decimal}

pure identity(value) { value }
pure invoke(callback, value) { callback(value) }
let alias = identity
print ${invoke(alias, 7)} ${invoke(alias, "word")} ${invoke(alias, false)}

pure identity(value) { value }
pure twice(callback) {
  let number: Int = callback(1)
  let text: Str = callback("word")
  number
}
let _ = twice(identity)
